local root='/Users/ryanmorrison/Documents/Codex/2026-10-25/visit-https-cerebralvalley-ai-e-meta/outputs/godmode'
local function read(path)local f=assert(io.open(path));local s=f:read('*a');f:close();return json.decode(s)end
local report={version=1,passed=true,atlases={}}
for _,name in ipairs({'characters','foreground'})do
 local data=read(root..'/public/assets/cozy/'..name..'.json');local im=Image{fromFile=root..'/public/assets/cozy/'..name..'.png'};local count=0;local empty={};local alphaMin=9999;local alphaMax=0;local actual={};local frames={};local visibleColors={}
 for key,v in pairs(data.frames)do
  count=count+1;local fr=v.frame;assert(fr.x>=0 and fr.y>=0 and fr.x+fr.w<=im.width and fr.y+fr.h<=im.height,key..' outside image');assert(v.anchor.x>=0 and v.anchor.x<=1 and v.anchor.y>=0 and v.anchor.y<=1,key..' bad anchor');assert(v.anchor.x==v.pixelAnchor.x/fr.w and v.anchor.y==v.pixelAnchor.y/fr.h,key..' mismatched units');assert(v.duration>0,key..' no duration')
  local opaque=0;local sig={};for y=fr.y,fr.y+fr.h-1 do for x=fr.x,fr.x+fr.w-1 do local col=im:getPixel(x,y);sig[#sig+1]=tostring(col);if app.pixelColor.rgbaA(col)>0 then opaque=opaque+1;visibleColors[col]=true end end end
  frames[key]={visiblePixels=opaque,width=fr.w,height=fr.h,durationMs=v.duration};if opaque==0 then empty[#empty+1]=key;assert(key=='crop.empty','unexpected empty frame '..key)end
  if name=='characters'then assert(fr.w==24 and fr.h==32,'incorrect character cell');assert(opaque>=130 and opaque<550,key..' unreadable body');assert(v.pixelAnchor.x==12 and v.pixelAnchor.y==31,'wrong feet')end
  alphaMin=math.min(alphaMin,opaque);alphaMax=math.max(alphaMax,opaque);actual[key]=table.concat(sig,',')
 end
 local animationCount=0;local distinct={};for key,a in pairs(data.animations)do animationCount=animationCount+1;assert(#a.frames>=2,key..' no animation');for i,k in ipairs(a.frames)do assert(data.frames[k],key..' references missing frame');assert(a.durations[i]==data.frames[k].duration,'timing mismatch')end;if name=='characters' and key:match('%.walk%.')then local seen={};local n=0;for _,k in ipairs(a.frames)do if not seen[actual[k]]then seen[actual[k]]=true;n=n+1 end end;assert(n==4,key..' must have four distinct walk poses');distinct[key]=n end end
 local colorCount=0;for _ in pairs(visibleColors)do colorCount=colorCount+1 end
 assert(name~='characters' or(count==288 and animationCount==96),'character completeness');report.atlases[name]={image={width=im.width,height=im.height},namedFrames=count,animations=animationCount,emptyFrames=empty,visiblePixelRange={min=alphaMin,max=alphaMax},actualNontransparentRgbaColors=colorCount,walkUniquePoses=distinct,frames=frames}
 -- The editable palette matches actual RGBA colors used by each native atlas.
 local s=Sprite{fromFile=root..'/art/cozy/'..name..'.aseprite'};local sorted={};for c in pairs(visibleColors)do sorted[#sorted+1]=c end;table.sort(sorted);local pal=Palette(math.min(256,#sorted));for i=1,math.min(256,#sorted)do local c=sorted[i];pal:setColor(i-1,Color{r=app.pixelColor.rgbaR(c),g=app.pixelColor.rgbaG(c),b=app.pixelColor.rgbaB(c),a=app.pixelColor.rgbaA(c)})end;s:setPalette(pal);s:saveAs(s.filename);if name=='characters' then for _,filename in ipairs({'characters-timeline.aseprite','walk-contact.aseprite'})do local edit=Sprite{fromFile=root..'/art/cozy/'..filename};edit:setPalette(pal);edit:saveAs(edit.filename)end end
end
local map=Image{fromFile=root..'/public/assets/cozy/map.png'};assert(map.width==512 and map.height==384,'map dimensions');local cols={};local n=0;for y=0,383 do for x=0,511 do local c=map:getPixel(x,y);assert(app.pixelColor.rgbaA(c)==255,'map should be opaque');if not cols[c]then cols[c]=true;n=n+1 end end end;assert(n<=256,'map palette not quantized');report.map={width=map.width,height=map.height,actualOpaqueColors=n,opaque=true};local s=Sprite{fromFile=root..'/art/cozy/map.aseprite'};local pal=Palette(n);local sorted={};for c in pairs(cols)do sorted[#sorted+1]=c end;table.sort(sorted);for i,c in ipairs(sorted)do pal:setColor(i-1,Color{r=app.pixelColor.rgbaR(c),g=app.pixelColor.rgbaG(c),b=app.pixelColor.rgbaB(c),a=255})end;s:setPalette(pal);s:saveAs(s.filename)
local f=assert(io.open(root..'/art/cozy/native-qa.json','w'));f:write(json.encode(report));f:write('\n');f:close();print(json.encode({passed=true,characters=report.atlases.characters.namedFrames,animations=report.atlases.characters.animations,foreground=report.atlases.foreground.namedFrames,mapColors=n}))
